// Runs in Storybook's docgen worker thread (`experimental_docgenProvider`). For a story file it resolves
// `meta.component` the way Storybook does, finds that component in a caliper-docgen session, and answers with argTypes
// converted by React's rules. Anything it can't document goes to the next provider, React's own.

import { readFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import type { RdtComponentDoc } from 'caliper-docgen-napi'
import {
  STORY_FILE_TEST_REGEXP,
  createMetaComponentResolver,
  extractDeclaredSubcomponents,
  getComponentIdFromEntry,
  getStoryImportPathFromEntry,
} from 'storybook/internal/common'
import { type CsfFile, extractComponentDescription, extractDescription, loadCsf } from 'storybook/internal/csf-tools'
import { logger } from 'storybook/internal/node-logger'
import type { DocgenMiddleware, DocgenPayload, IndexEntry } from 'storybook/internal/types'
import { type ExtractArgTypes, loadExtractArgTypes, toArgTypes } from './arg-types.js'
import type { CaliperStorybookOptions } from './index.js'
import { DocgenSession, type SessionBinding } from './session.js'
import { assertValidOptions } from './validate.js'

type Subcomponent = NonNullable<DocgenPayload['subcomponents']>[string]

interface StoryFile {
  csf: CsfFile
  storyPath: string
  importPath: string
}

/**
 * `csf`'s story file as the resolver reads it, with `meta.component` being `expression`. The file is parsed again with
 * the expression appended as a statement, so every node has source text for the resolver to report an expression it
 * cannot follow, and every statement stays: the resolver follows the story's imports and local bindings
 * (`const parts = { Item }`) as it does for the written meta, whichever form the meta takes (`export default`,
 * `export { meta as default }`, a CSF factory's `preview.meta()`).
 */
function storyFor(csf: CsfFile, storyPath: string, expression: string): CsfFile {
  const code = `${csf.editor.toString()}\n;(${expression})\n`
  const parsed = loadCsf(code, { fileName: storyPath, makeTitle: () => 'caliper-docgen' }).parse()
  const statement = parsed.program.body.at(-1)
  if (statement?.type !== 'ExpressionStatement') throw new Error(`no expression to resolve for ${expression}`)
  // The parsed file stands in for the written one, with only its component swapped.
  return Object.create(parsed, { _metaAnnotations: { value: { component: statement.expression } } })
}

/** The resolver threw instead of answering: a defect to hand to the next provider, not a fact about one subcomponent. */
class ResolverFailureError extends Error {
  override name = 'ResolverFailureError'
}

/** caliper keeps one value per JSDoc tag; Storybook lists every value. */
function tagLists(tags: Record<string, string>): Record<string, string[]> | undefined {
  const entries = Object.entries(tags)
  return entries.length > 0 ? Object.fromEntries(entries.map(([tag, value]) => [tag, [value]])) : undefined
}

/** Says there is no component `name` in `path`, and which ones the file does have. */
function noComponent(session: DocgenSession, name: string, path: string): string {
  const names = session.namesIn(path)
  const choice = names.length > 0 ? `; its components are ${names.join(', ')}` : ''
  return `caliper-docgen found no component ${name} in ${path}${choice}`
}

export function createDocgenProvider(
  options: CaliperStorybookOptions = {},
  binding?: SessionBinding,
): DocgenMiddleware {
  assertValidOptions(options)
  const cwd = process.cwd()
  const sessionOptions = {
    srcDirs: (options.srcDirs ?? ['src']).map((dir) => resolve(cwd, dir)),
    exclude: options.exclude,
    tsconfigPath: options.tsconfigPath && resolve(cwd, options.tsconfigPath),
    skipHtmlProps: options.skipHtmlProps,
    htmlAttributes: options.htmlAttributes,
    cache: options.cache,
    // Richer than Storybook's own docgen by default: caliper-docgen is fast enough to read the dependencies' types.
    loadDependencies: options.loadDependencies ?? true,
    collapseInheritedProps: options.collapseInheritedProps ?? 'none',
    lazy: options.lazy,
    warmUp: options.warmUp,
    fillAfter: options.fillAfter,
    semanticTypes: options.semanticTypes,
    tscPath: options.tscPath,
    semanticWaitMs: options.semanticWaitMs,
    semanticWaitEmptyMs: options.semanticWaitEmptyMs,
  }
  // The native binding loads on the first story request, not when Storybook starts the worker.
  let sessionPromise: Promise<DocgenSession> | undefined
  async function getSession(): Promise<DocgenSession> {
    sessionPromise ??= (async () =>
      new DocgenSession(sessionOptions, binding ?? (await import('caliper-docgen-napi'))))()
    const attempt = sessionPromise
    try {
      return await attempt
    } catch (error) {
      // A binding that failed to load is tried again by the next request, not remembered as failed.
      if (sessionPromise === attempt) sessionPromise = undefined
      throw error
    }
  }
  // A session that cannot start is reported once at a level a developer sees, then every story falls back quietly.
  let startFailureReported = false

  let started = false
  let refreshFailureReported = false

  /**
   * The session, up to date with the files. A failure before the first successful `fresh()` is a failure to start;
   * after it, a failure is a refresh of a running session and is worded as one. Each is reported once until a
   * `fresh()` succeeds again, and thrown for the fallback either way.
   */
  async function freshSession(): Promise<DocgenSession> {
    try {
      const session = await getSession()
      await session.fresh()
      started = true
      startFailureReported = false
      refreshFailureReported = false
      return session
    } catch (error) {
      const { message } = error as Error
      if (!started && !startFailureReported) {
        startFailureReported = true
        logger.warn(`[caliper-docgen] could not start: ${message}; Storybook's own docgen answers instead`)
      } else if (started && !refreshFailureReported) {
        refreshFailureReported = true
        logger.warn(`[caliper-docgen] could not refresh: ${message}; Storybook's own docgen answers instead`)
      }
      throw error
    }
  }
  const metaComponent = createMetaComponentResolver()
  const resolveMeta = (csf: CsfFile, storyPath: string) => {
    try {
      return metaComponent(csf, storyPath)
    } catch (error) {
      throw new ResolverFailureError((error as Error).message)
    }
  }
  const fallback = options.fallback ?? 'degraded'
  let extractArgTypes: Promise<ExtractArgTypes> | undefined
  // A component handed on is reported once, not on every story request that names it.
  const reported = new Set<string>()

  function reportFallback(key: string, reason: string): void {
    if (reported.has(key)) return
    reported.add(key)
    logger.warn(`[caliper-docgen] ${key}: ${reason}; Storybook's own docgen answers instead`)
  }

  /** The session key and file `target`'s component points at, or an error that says what the session had instead. */
  function locate(session: DocgenSession, target: CsfFile, storyPath: string): { key: string; path: string } {
    const resolution = resolveMeta(target, storyPath)
    if ('component' in resolution) {
      const { path, exportName, localName } = resolution.component
      if (!path) throw new Error(`no file for the import of ${exportName}`)
      const key = session.resolveExport(path, exportName, localName)
      if (key) return { key, path }
      // Storybook follows `Select.Option` into the module that declares `Option` and answers with that local name, which
      // caliper may know as `Select.Option`.
      const member = memberComponent(session, target, storyPath)
      if (member) return member
      throw new Error(noComponent(session, exportName, path))
    }
    // A member Storybook cannot follow into a module's source (`Select.Option` of a named import from a barrel).
    const member = memberComponent(session, target, storyPath)
    if (member) return member
    throw new Error(`meta.component: ${resolution.reason}`)
  }

  /** The sub-component a `Namespace.Member` expression names, when `Namespace` is a named or default import. */
  function memberComponent(
    session: DocgenSession,
    csf: CsfFile,
    storyPath: string,
  ): { key: string; path: string } | undefined {
    const node = csf._metaAnnotations.component as
      | {
          type?: string
          computed?: boolean
          object?: { type?: string; name?: string }
          property?: { type?: string; name?: string }
        }
      | undefined
    if (node?.type !== 'MemberExpression' || node.computed) return undefined
    if (node.object?.type !== 'Identifier' || !node.object.name || !node.property?.name) return undefined
    const owner = resolveMeta(storyFor(csf, storyPath, node.object.name), storyPath)
    if (!('component' in owner) || !owner.component.path) return undefined
    const { path, exportName, localName } = owner.component
    const key = session.keyOfMember({ exportName, localName }, node.property.name, path)
    return key ? { key, path } : undefined
  }

  /**
   * The session key, file and documentation of the component `name` (default: `meta.component`) names, or why there
   * is none. The caller has brought the session up to date for this request.
   */
  async function component(
    csf: CsfFile,
    storyPath: string,
    name?: string,
  ): Promise<{ key: string; path: string; doc: RdtComponentDoc }> {
    const target = name ? storyFor(csf, storyPath, name) : csf
    const session = await getSession()
    const { key, path } = locate(session, target, storyPath)
    const { doc, degradedBy } = session.documentation(key)
    if (fallback === 'degraded' && degradedBy.length > 0) {
      const reason = degradedBy.join('; ')
      reportFallback(key, reason)
      throw new Error(`${key}'s props may be incomplete: ${reason}`)
    }
    if (!doc) throw new Error(noComponent(session, key, path))
    return { key, path, doc }
  }

  async function argTypes(doc: RdtComponentDoc): Promise<DocgenPayload['argTypes']> {
    extractArgTypes ??= loadExtractArgTypes()
    return toArgTypes(doc, await extractArgTypes)
  }

  async function subcomponent(
    { csf, storyPath, importPath }: StoryFile,
    { name, componentName }: { name: string; componentName: string },
  ): Promise<Subcomponent> {
    try {
      const { path, doc } = await component(csf, storyPath, componentName)
      const { description, summary, jsDocTags } = extractComponentDescription(
        undefined,
        doc.description || undefined,
        tagLists(doc.tags),
      )
      return { name, path, description, summary, jsDocTags, argTypes: await argTypes(doc) }
    } catch (error) {
      if (error instanceof ResolverFailureError) throw error
      return {
        name,
        path: importPath,
        jsDocTags: {},
        error: { name: 'No component import found', message: `${componentName}: ${(error as Error).message}` },
      }
    }
  }

  async function document(entry: IndexEntry, importPath: string): Promise<DocgenPayload> {
    const storyPath = resolve(cwd, importPath)
    const code = await readFile(storyPath, 'utf8')
    const csf = loadCsf(code, { fileName: storyPath, makeTitle: () => entry.title }).parse()
    // One look at the files for the story and its subcomponents: they are all answered from the same moment.
    await freshSession()
    const { doc } = await component(csf, storyPath)
    const { description, summary, jsDocTags } = extractComponentDescription(
      extractDescription(csf._metaStatement, csf.editor) || undefined,
      doc.description || undefined,
      tagLists(doc.tags),
    )
    const declared = extractDeclaredSubcomponents(csf)
    const subcomponents = Object.fromEntries(
      await Promise.all(
        declared.map(async (declaration) => [
          declaration.name,
          await subcomponent({ csf, storyPath, importPath }, declaration),
        ]),
      ),
    )
    return {
      id: getComponentIdFromEntry(entry),
      name: csf._meta?.component ?? entry.title.split('/').at(-1)!.replaceAll(/\s+/g, ''),
      path: importPath,
      description,
      summary,
      jsDocTags,
      argTypes: await argTypes(doc),
      ...(declared.length > 0 ? { subcomponents } : {}),
    }
  }

  return (next) => async (input) => {
    const importPath = getStoryImportPathFromEntry(input.entry)
    if (!importPath || !STORY_FILE_TEST_REGEXP.test(importPath)) return next(input)
    try {
      return await document(input.entry, importPath)
    } catch (error) {
      logger.debug(`[caliper-docgen] ${importPath}: ${(error as Error).message}; asking the next docgen provider`)
      return next(input)
    }
  }
}
import { dirname, resolve } from 'node:path'
import type * as Napi from 'caliper-docgen-napi'
import type { Diagnostic, IncrementalUpdate, RdtComponentDoc, SessionIndex } from 'caliper-docgen-napi'
import { Fill } from './fill.js'
import { toNapiOptions, type SessionOptions } from './options.js'
import {
  buildLookups,
  diagnosticId,
  exportKey,
  incompleteMessages,
  only,
  type ImportName,
  refOf,
  type ComponentRef,
  type Lookups,
} from './lookups.js'
import { assertSchemaVersion, expandDiagnostics } from './schema.js'

export type { SessionOptions } from './options.js'

/** The binding calls the session makes, so tests can stand in for the native module. */
export type SessionBinding = Pick<
  typeof Napi,
  | 'createSession'
  | 'initializeSessionIndex'
  | 'ensureFresh'
  | 'sessionDocgenInfo'
  | 'sessionComponentAnswers'
  | 'sessionWarmUp'
  | 'closeSession'
>

/** How many components the background warm-up resolves, spread over the project. */
const WARM_UP_COMPONENTS = 8
const FILL_AFTER = 0
/** The most components `sessionWarmUp` takes: all of them. */
const ALL_COMPONENTS = 2 ** 32 - 1

/** What the session says about one component: its documentation and why its props may be incomplete. */
export interface Documentation {
  doc: RdtComponentDoc | undefined
  /** The messages of the warnings and errors that say the props may be incomplete; empty when none does. */
  degradedBy: string[]
}

/**
 * One watch session over the source directories, created on first use. Storybook gives no file events to a docgen
 * worker, so `fresh()` has the native session compare every source file's mtime and size with the last look and apply
 * the changed ones before a request is answered: an answer never trails a saved edit. The session holds the props;
 * this class holds only where each component lives and, for an eager session, which ones a diagnostic says are
 * incomplete. A lazy session (the default) resolves a component when `documentation` asks, and holds no answers.
 */
export class DocgenSession {
  private readonly components = new Map<string, ComponentRef>()
  private readonly diagnostics = new Map<string, Diagnostic>()
  /** Rebuilt from `components` and `diagnostics` on the first lookup after either changes. */
  private index: Lookups | undefined
  private sessionId: number | undefined
  private ready: Promise<void> | undefined
  private checking: Promise<void> | undefined
  private queued: Promise<void> | undefined
  private latestRevision = 0
  private readonly fill: Fill
  private readonly options: SessionOptions
  private readonly napi: SessionBinding

  constructor(options: SessionOptions, napi: SessionBinding) {
    this.options = options
    this.napi = napi
    this.fill = new Fill(options.fillAfter ?? FILL_AFTER)
  }

  private napiOptions(): Napi.JsExtractOptions {
    return toNapiOptions(this.options, this.lazy)
  }

  private get lazy(): boolean {
    return this.options.lazy ?? true
  }

  private async initialize(): Promise<void> {
    this.sessionId = this.napi.createSession(this.napiOptions())
    await this.reindex()
    // Not awaited: the first story answers as soon as it can, and shares what the warm-up has loaded by then.
    if (this.lazy && this.options.warmUp === true) void this.warmUp(this.sessionId, WARM_UP_COMPONENTS)
  }

  /** Best effort: a background resolution that fails costs the stories the time it would have saved. */
  private async warmUp(sessionId: number, count: number): Promise<void> {
    try {
      await this.napi.sessionWarmUp(sessionId, count)
    } catch {
      // The stories resolve what they need themselves.
    }
  }

  /** Reads where every component is declared (and, for an eager session, which diagnostics affect them). */
  private async reindex(): Promise<void> {
    const json = await this.napi.initializeSessionIndex(this.sessionId!, this.napiOptions())
    const output = assertSchemaVersion(JSON.parse(json) as SessionIndex, 'session index')
    this.components.clear()
    for (const [key, entry] of Object.entries(output.components)) {
      this.components.set(key, refOf(entry))
    }
    for (const diagnostic of expandDiagnostics(output.diagnostics, output.nameLists)) {
      this.diagnostics.set(diagnosticId(diagnostic), diagnostic)
    }
    this.index = undefined
  }

  private apply(update: IncrementalUpdate): void {
    if (update.revision <= this.latestRevision) return
    this.latestRevision = update.revision
    this.index = undefined
    for (const key of update.removedKeys) this.components.delete(key)
    update.updatedKeys.forEach((key, i) => {
      const entry = update.updatedComponents[i]
      if (entry) this.components.set(key, refOf(entry))
    })
    for (const diagnostic of expandDiagnostics(update.removedDiagnostics, update.nameLists)) {
      this.diagnostics.delete(diagnosticId(diagnostic))
    }
    for (const diagnostic of expandDiagnostics(update.diagnostics, update.nameLists)) {
      this.diagnostics.set(diagnosticId(diagnostic), diagnostic)
    }
  }

  private async check(): Promise<void> {
    const json = await this.napi.ensureFresh(this.sessionId!)
    const update = assertSchemaVersion(JSON.parse(json) as IncrementalUpdate, 'update')
    if (this.lazy) {
      // A lazy update names the keys an edit can change but carries no component to place them, so look again at where
      // the components are; resolving none of them, that costs a parse-level listing.
      if (update.revision > this.latestRevision) {
        this.latestRevision = update.revision
        if (update.updatedKeys.length > 0 || update.removedKeys.length > 0) await this.reindex()
      }
      return
    }
    this.apply(update)
  }

  /**
   * Resolves once the session holds every edit saved before the call. Concurrent callers share one look at the
   * files; a caller arriving while a look is under way waits for it and then takes its own, since that look may
   * have started before the caller's edit.
   */
  async fresh(): Promise<void> {
    this.ready ??= this.initialize()
    const attempt = this.ready
    try {
      await attempt
    } catch (error) {
      // A failed start is not kept: the next request starts again, with nothing left over from this attempt. Of
      // several callers that shared it, the first to see it fail clears it.
      if (this.ready === attempt) {
        this.ready = undefined
        this.discard()
      }
      throw error
    }
    if (!this.checking) return this.look()
    this.queued ??= this.lookAfter(this.checking)
    return this.queued
  }

  /** Releases the native session a failed start created, if it got that far. */
  private discard(): void {
    if (this.sessionId === undefined) return
    try {
      this.napi.closeSession(this.sessionId)
    } catch {
      // The attempt already failed; the next one makes its own session.
    }
    this.sessionId = undefined
  }

  private async lookAfter(earlier: Promise<void>): Promise<void> {
    try {
      await earlier
    } catch {
      // That look's failure belongs to its own callers.
    }
    this.queued = undefined
    return this.look()
  }

  /** Starts a look and publishes it in `checking` before yielding, so a caller arriving next sees it. */
  private async look(): Promise<void> {
    const look = this.check()
    this.checking = look
    try {
      await look
    } finally {
      if (this.checking === look) this.checking = undefined
    }
  }

  private lookups(): Lookups {
    return (this.index ??= buildLookups(this.components, this.diagnostics.values()))
  }

  /**
   * The key of the component `path` exports as `exportName` (`default` for the default export), or, with `members`, of
   * the sub-component reached through them (`Menu.Item` beside `export default Menu` is `default`, `['Item']`).
   */
  keyOfExport(path: string, exportName: string, members: readonly string[] = []): string | undefined {
    const at = exportKey(resolve(path), exportName, members)
    return only(this.lookups().byExport.get(at))
  }

  /**
   * The key of the component `exportName` names in `path`. A path with no components is a barrel that re-exports them,
   * which `exports` does not record, so it falls back to the one component with that display name.
   */
  keyOf(path: string, exportName: string): string | undefined {
    const { byFile, byName } = this.lookups()
    if (byFile.has(resolve(path))) return this.keyOfExport(path, exportName)
    return exportName === 'default' ? undefined : only(byName.get(exportName))
  }

  /**
   * `keyOf`, else for a default export no component has, the component named as the story named its default import
   * (`importedAs`).
   */
  resolveExport(path: string, exportName: string, importedAs?: string): string | undefined {
    const key = this.keyOf(path, exportName)
    if (key || exportName !== 'default' || importedAs === undefined) return key
    const inFile = this.lookups().byFile.get(resolve(path))
    return only(inFile?.filter((each) => this.components.get(each)?.displayName === importedAs))
  }

  /** The key of `namespace.property` (`Select.Option`): attached to the export in `near`, else by display name beside it. */
  keyOfMember(namespace: ImportName, property: string, near: string): string | undefined {
    const attached = this.keyOfExport(near, namespace.exportName, [property])
    if (attached) return attached
    const { byName } = this.lookups()
    const names = [namespace.localName, namespace.exportName]
    const matches = [...new Set(names.flatMap((name) => byName.get(`${name}.${property}`) ?? []))]
    if (matches.length <= 1) return matches[0]
    const dir = dirname(resolve(near))
    const beside = matches.filter((key) => dirname(this.components.get(key)?.filePath ?? '') === dir)
    return beside.length === 1 ? beside[0] : undefined
  }

  /** The display names of the components in `path`, to say what a failed lookup had to choose from. */
  namesIn(path: string): string[] {
    const keys = this.lookups().byFile.get(resolve(path)) ?? []
    return keys.flatMap((key) => this.components.get(key)?.displayName ?? [])
  }

  /** Whether a warning or error says `key`'s props may be incomplete. An eager session only: see `documentation`. */
  degraded(key: string): boolean {
    return this.degradedBy(key).length > 0
  }

  /** The messages of the warnings and errors that say `key`'s props may be incomplete. */
  degradedBy(key: string): string[] {
    return [...(this.lookups().degradedBy.get(key) ?? [])]
  }

  /**
   * The documentation of `key` and why its props may be incomplete. A lazy session resolves the component now, or
   * answers from what an earlier story resolved; nothing is kept here, so an edit cannot leave a stale answer behind.
   */
  documentation(key: string): Documentation {
    if (!this.lazy) return { doc: this.docgenInfo(key), degradedBy: this.degradedBy(key) }
    if (this.sessionId === undefined) return { doc: undefined, degradedBy: [] }
    const answers = JSON.parse(this.napi.sessionComponentAnswers(this.sessionId, [key])) as Record<
      string,
      { docgenInfo: RdtComponentDoc; diagnostics: Diagnostic[] }
    >
    const answer = answers[key]
    if (!answer) {
      // The listing includes a re-export of a package component that has nothing to show; it is no component.
      if (this.components.delete(key)) this.index = undefined
      return { doc: undefined, degradedBy: [] }
    }
    if (this.fill.asked(key)) void this.warmUp(this.sessionId, ALL_COMPONENTS)
    return { doc: answer.docgenInfo, degradedBy: incompleteMessages(answer.diagnostics) }
  }

  docgenInfo(key: string): RdtComponentDoc | undefined {
    if (this.sessionId === undefined) return undefined
    const docs = JSON.parse(this.napi.sessionDocgenInfo(this.sessionId, [key])) as Record<string, RdtComponentDoc>
    return docs[key]
  }

  close(): void {
    if (this.sessionId !== undefined) this.napi.closeSession(this.sessionId)
  }
}

