// Registered after caliper's provider, so it wraps it: logs each docgen request with wall-clock start and end.
import { appendFileSync } from 'node:fs'

export function createDocgenProvider(options) {
  return (next) => async (input) => {
    const start = Date.now()
    const payload = await next(input)
    const argTypes = payload?.argTypes ? Object.keys(payload.argTypes).length : -1
    if (options.log) {
      const row = { event: 'docgen', importPath: input.entry.importPath, start, end: Date.now(), argTypes }
      appendFileSync(options.log, `${JSON.stringify(row)}\n`)
    }
    return payload
  }
}

