// Storybook config for the prefetch measurement; CALIPER_OPTIONS (JSON) is the addon's options, TRACE_LOG the trace file.
const trace = '/Users/gabe/Projects/caliper-fixtures/prefetch/trace-provider.mjs'

export default {
  framework: '@local/sb11-react-vite',
  stories: ['../src/stories/*.stories.tsx'],
  addons: [{ name: 'caliper-docgen-storybook', options: JSON.parse(process.env.CALIPER_OPTIONS ?? '{}') }],
  experimental_docgenProvider: (existing = []) => [
    ...existing,
    { moduleSpecifier: trace, options: { log: process.env.TRACE_LOG } },
  ],
  viteFinal: (config) => ({ ...config, resolve: { ...(config.resolve ?? {}), dedupe: ['react', 'react-dom'] } }),
  core: { disableTelemetry: true },
}

// Registered after caliper's provider, so it wraps it: logs each docgen request with wall-clock start and end.
import { appendFileSync } from 'node:fs'

export function createDocgenProvider(options) {
  return (next) => async (input) => {
    const start = Date.now()
    const payload = await next(input)
    const argTypes = payload?.argTypes ? Object.keys(payload.argTypes).length : -1
    if (options.log) {
      const row = { event: 'docgen', importPath: input.entry.importPath, start, end: Date.now(), argTypes }
      appendFileSync(options.log, `${JSON.stringify(row)}\n`)
    }
    return payload
  }
}

