)
s = s.replace('  babelParser as babelParser2,\n  extractMockCalls as extractMockCalls2,\n', '')
s = s.replace(
  '// src/plugins/vite-mock/plugin.ts',
  '// src/plugins/vite-mock/plugin.ts\nconst babelParser2 = undefined, extractMockCalls2 = () => [];',
)
writeFileSync(file, s)

